@prefix mlm: <https://w3id.org/ogc/stac/mlm/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/registers/ml-activities/landCoverModel> ;
            sh:resultMessage "Less than 1 values on ex:landCoverModel->( mlm:input [ sh:zeroOrMorePath rdf:rest ] rdf:first )" ;
            sh:resultPath ( mlm:input [ sh:zeroOrMorePath rdf:rest ] rdf:first ) ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:minCount 1 ;
                    sh:node mlm:ModelInputShape ;
                    sh:path ( mlm:input [ sh:zeroOrMorePath rdf:rest ] rdf:first ) ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/registers/ml-activities/landCoverModel> ;
            sh:resultMessage "Less than 1 values on ex:landCoverModel->( mlm:tasks [ sh:zeroOrMorePath rdf:rest ] rdf:first )" ;
            sh:resultPath ( mlm:tasks [ sh:zeroOrMorePath rdf:rest ] rdf:first ) ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:class skos:Concept ;
                    sh:minCount 1 ;
                    sh:path ( mlm:tasks [ sh:zeroOrMorePath rdf:rest ] rdf:first ) ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/registers/ml-activities/landCoverModel> ;
            sh:resultMessage "Less than 1 values on ex:landCoverModel->( mlm:output [ sh:zeroOrMorePath rdf:rest ] rdf:first )" ;
            sh:resultPath ( mlm:output [ sh:zeroOrMorePath rdf:rest ] rdf:first ) ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:minCount 1 ;
                    sh:node mlm:ModelOutputShape ;
                    sh:path ( mlm:output [ sh:zeroOrMorePath rdf:rest ] rdf:first ) ] ] .

